import{z as r,x as A,o as n,c as m,q as l,j as i,D as t,d as o,s as d,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Document attention mask","description":"","frontmatter":{"title":"Document attention mask","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/document-masking.md","filePath":"llm/document-masking.md","lastUpdated":1791063341000}'),c={name:"llm/document-masking.md"};function p(B,a,u,h,k,D){const s=A("Mermaid");return n(),m("div",null,[a[2]||(a[2]=l('<h1 id="document-attention-mask" tabindex="-1">Document attention mask <a class="header-anchor" href="#document-attention-mask" aria-label="Permalink to &quot;Document attention mask&quot;">​</a></h1><div class="epigraph"><p>把「这篇与那篇不可见」写成注意力在 softmax 之前的结构：块内因果或双向，块间为零。它是一张图，不是一个分隔符。</p><footer>—— 工程对象：块对角掩码；形式化与等价性见 Krell et al., arXiv:2107.02027；融合核见 Dao et al. FlashAttention 变长接口</footer></div><p>因果掩码回答「未来不可见」。<strong>Document attention mask</strong> 再加一条：即便在时间上靠前，若所属文档不同，也不可见。它出现在 packing、多文档 batch、以及「同一请求里拼了系统提示 + 多段检索」的服务侧。数学上是块对角（再与因果下三角求交）；工程上可以是稠密 \\(n\\times n\\) 布尔、FlexAttention 的 <code>document_id</code>、或 <code>cu_seqlens</code> 把每篇当成独立变长序列。本篇把掩码当一等公民写清形状、与 RoPE、与 KV 缓存的交叉；装箱算法与填充率见 <a href="/llm/packing-cross-doc-mask">跨文档 packing 掩码</a> 与 <a href="/llm/sequence-packing">packing</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>令序列 \\(x_{1:n}\\) 来自文档 \\(d(t)\\in\\{1,\\ldots,M\\}\\)。标准因果注意力的允许集是 \\(\\{(t,s):s\\le t\\}\\)。文档掩码的允许集是</p> \\[\\mathcal{A}=\\bigl\\{(t,s): s\\le t,\\ d(t)=d(s)\\bigr\\} \\]<p>（编码器双向则去掉 \\(s\\le t\\)，只保留 \\(d(t)=d(s)\\)）。\\(\\mathcal{A}\\) 的补集在 softmax 前设为 \\(-\\infty\\)。没有这张图，模型没有「文档」概念，只有「更早的 token」。分隔符可以出现在嵌入里，但嵌入不能删掉一条已经算出来的边。<span class="marginnote">「块对角」画出来就是：把整批 token 排成方阵，只有同一篇的行列交叉处有值，几篇文章变成几个方块沿对角线排开，方块之外全黑。可以想象成每篇文档一间独立教室，教室之间没有窗户——因果掩码只规定「不许看后排」，文档掩码再规定「隔壁教室也不许看」。</span></p><p>服务侧同样有文档：系统提示、工具结果、多文件上下文若共享因果窗，后文件可以抄前文件机密或检索碎片。训练用了 document mask、推理不用，或反过来，都是分布偏移。问题是把 \\(d(t)\\) 从数据管道传到注意力核，且与 GQA、滑窗、块稀疏兼容。</p><h3 id="块对角不是滑窗" tabindex="-1">块对角不是滑窗 <a class="header-anchor" href="#块对角不是滑窗" aria-label="Permalink to &quot;块对角不是滑窗&quot;">​</a></h3><p>滑窗限制的是距离 \\(|t-s|\\le w\\)，与文档无关。文档掩码限制的是等价类 \\(d\\)。两者可叠加：篇内滑窗、篇间仍全断。Longformer / BigBird 的全局 token 若跨篇共享，会重新打通块对角，必须规定全局点只属于一篇或禁止跨篇全局。不要把「局部注意力」当成已经做了文档隔离。</p><p><span class="marginnote">Padding 掩码切断 pad 位置；文档掩码切断不同 \\(d\\)。实现里常或成一张加法掩码。漏掉 pad 会让 pad 嵌入污染；漏掉 \\(d\\) 会让上一篇污染。日志应分开统计两种无效边的数量，而不是只报「用了 attention mask」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据侧输出 <code>document_ids</code> 或 <code>cu_seqlens</code>。核侧三条路径：</p><p><strong>稠密加性掩码。</strong> 构造 \\(M\\in\\mathbb{R}^{n\\times n}\\)，\\(M_{ts}=0\\) 若 \\((t,s)\\in\\mathcal{A}\\)，否则 \\(-10^4\\) 量级。与 \\(QK^\\top/\\sqrt{d_k}\\) 相加。实现简单，FlashAttention 原初接口不完全吃任意加性掩码，可能回退，内存 \\(O(n^2)\\)。</p><p><strong>变长分段。</strong> 把每篇当成独立序列，累积长度 <code>cu_seqlens</code>，核在段内做因果 SDPA，段间无边。这是 document mask 的零物化实现，复杂度 \\(\\sum_m n_m^2\\)。要求同一 batch 的段能拼成核所支持的布局（如 THD）。</p><p><strong>文档 id 比较。</strong> FlexAttention 等把 <code>d[t]==d[s] &amp; causal</code> 编译进核。适合不规则块（一篇被切断成两段但共享 id 的情况要先定义：通常切断后视为两篇，除非显式续段）。</p><h3 id="与位置、与-kv" tabindex="-1">与位置、与 KV <a class="header-anchor" href="#与位置、与-kv" aria-label="Permalink to &quot;与位置、与 KV&quot;">​</a></h3><p>RoPE 相位按位置下标。文档掩码不自动重置位置：若下标跨篇连续，篇首仍带大相位，即使看不见上一篇。等价训练通常<strong>按篇重置位置</strong>，与掩码是两件套。KV 缓存按物理下标存；decode 时新 token 的 \\(d\\) 若仍是当前篇，只应 vis 本篇已缓存键，或在分页里把上一篇的页标为不可见。连续批处理中不同请求本就是不同文档，请求间隔离是调度器的 mask，请求内多文档才是本篇对象。<span class="marginnote">位置不重置的后果：第二篇的第一个 token 带着「第 5001 位」的旋转相位，模型只能靠相位猜「我是新开头」。掩码管「能看谁」，位置管「我排在哪」，两件事必须一起改，只改掩码等于换了门牌却没换门锁。</span></p>',18)),(n(),i(E,null,{default:t(()=>[d(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22token%20%E5%BA%8F%E5%88%97%22%5D%20--%3E%20DID%5B%22document_id%20%2F%20%E6%AE%B5%E8%BE%B9%E7%95%8C%22%5D%0A%20%20DID%20--%3E%20CAUS%5B%22%E4%B8%8E%E5%9B%A0%E6%9E%9C%E4%B8%8B%E4%B8%89%E8%A7%92%E6%B1%82%E4%BA%A4%22%5D%0A%20%20CAUS%20--%3E%20A%5B%22%E5%85%81%E8%AE%B8%E9%9B%86%20A%22%5D%0A%20%20A%20--%3E%20DENSE%5B%22%E7%A8%A0%E5%AF%86%E5%8A%A0%E6%80%A7%E6%8E%A9%E7%A0%81%22%5D%0A%20%20A%20--%3E%20VAR%5B%22cu_seqlens%20%E5%8F%98%E9%95%BF%E6%A0%B8%22%5D%0A%20%20A%20--%3E%20FLEX%5B%22id%20%E6%AF%94%E8%BE%83%E7%BC%96%E8%AF%91%E6%A0%B8%22%5D%0A%20%20DENSE%20--%3E%20S%5B%22Softmax%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20VAR%20--%3E%20S%0A%20%20FLEX%20--%3E%20S%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"BERT 式 NSP 需要两句可见性与文档掩码同时存在：句子 A/B 在同一包内可能同 id 或不同 id，Krell 等为此改了按序列计的损失。因果 LM 没有 NSP，文档掩码就是块内下三角。混合窗口（Gemma 式局部+全局层）时，全局层若看满 \\(L\\)，跨篇边会在全局层重现——要在全局层也应用同一 \\(\\mathcal{A}\\)，或接受「只有全局层泄漏」。这是架构级选择，应写入报告。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"softmax 行归一化只在 \\(\\mathcal{A}\\) 的行支撑上发生。切断跨篇边后，质量不会分给另一篇，梯度也不会从另一篇的键流过来。这恢复「文档是独立抽样」的近似，使 packing 的硬件收益不改任务定义。与因果掩码求交保证自回归仍成立：篇内不能看未来。两者缺一，要么泄漏未来，要么泄漏邻篇。",-1)),(n(),i(E,null,{default:t(()=>[d(s,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20PACK%5B%22packing%20%E4%B8%80%E6%89%B9%EF%BC%9A%E6%96%87%E6%A1%A3A%204%20token%20%2B%20%E6%96%87%E6%A1%A3B%203%20token%22%5D%20--%3E%20Q%7B%22%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%E9%97%AE%EF%BC%9As%20%E5%90%8C%E7%AF%87%E4%B8%94%E6%9B%B4%E6%97%A9%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22A2%20%E7%9C%8B%20A1%22%7C%20IN%5B%22%E5%9D%97%E5%86%85%E5%9B%A0%E6%9E%9C%E8%BE%B9%EF%BC%9A%E4%BF%9D%E7%95%99%22%5D%0A%20%20Q%20--%3E%7C%22A4%20%E7%9C%8B%20B3%22%7C%20CROSS%5B%22%E8%B7%A8%E7%AF%87%E8%BE%B9%EF%BC%9A%E8%AE%BE%E4%B8%BA%20-inf%22%5D%0A%20%20Q%20--%3E%7C%22A2%20%E7%9C%8B%20A4%22%7C%20FUT%5B%22%E6%9C%AA%E6%9D%A5%E8%BE%B9%EF%BC%9A%E8%AE%BE%E4%B8%BA%20-inf%22%5D%0A%20%20IN%20--%3E%20S%5B%22softmax%20%E5%8F%AA%E5%9C%A8%E4%BF%9D%E7%95%99%E8%BE%B9%E4%B8%8A%E5%BD%92%E4%B8%80%E5%8C%96%22%5D%0A%20%20CROSS%20--%3E%20S%0A%20%20FUT%20--%3E%20S%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">可视化注意力时，若绘制了跨篇高权重，先查 mask 是否坏，再解释「模型学会了跨文档推理」。训练若声称 document-masked，图上不应出现块外质量。</span></p><h3 id="和前缀掩码、和检索拼接" tabindex="-1">和前缀掩码、和检索拼接 <a class="header-anchor" href="#和前缀掩码、和检索拼接" aria-label="Permalink to &quot;和前缀掩码、和检索拼接&quot;">​</a></h3><p>前缀 LM（T5 一部分设定、UL2）允许前缀双向、后缀因果，那是另一张图。文档掩码可以叠在前缀 LM 上：每篇内部前缀双向，篇间仍断。检索增强把多段 hit 拼进上下文，若不做 document mask，模型把 hit 当连续章节；若做，则每段独立，更像「多段只读记忆」。产品要的是哪一种，不能从训练 packing 默认值推断。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>任意加性掩码与高度融合的 FA2/FA3 核不总兼容，团队用 <code>cu_seqlens</code> 换速度时，必须保证切段与 \\(d(t)\\) 一致，否则静默跨篇。GQA 下掩码按查询行定义，KV 头共享不改变 \\(\\mathcal{A}\\)。滑窗 + 文档 + 因果 三条件求交后，有效键更少，MFU 上升、长程依赖下降，是刻意的。</p><p>不要用 BOS/EOS 替换 \\(\\mathcal{A}\\)。不要假设推理框架默认 document mask：多数 chat 模板只有因果。训练用了、服务没用，表现为「喜欢把上一轮用户话当成本轮文档内上下文」——若上一轮本应隔离，这是 bug。评测长上下文 NIAH 若在单文档上做，与多文档 mask 无关；多针多文档测试才考这张图。<span class="marginnote">NIAH（needle in a haystack，大海捞针）是把一句关键信息埋进长上下文、看模型能否捞出来的测试。但把针和草堆放在同一篇文档里，根本用不到文档掩码——只有「针与草堆分属不同文档」的多针版本，才真正考这张图是否生效。</span></p><p><span class="marginnote">出处：Krell et al., arXiv:2107.02027（块对角以实现无污染 packing）；Vaswani et al. 2017（因果掩码作为前驱）；Dao et al. FlashAttention 变长 <code>cu_seqlens</code>；FlexAttention 文档 id 接口为工程实现。T5 / PaLM 的拼接是否带块对角，以各自报告为准，不可一律假定。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Document attention mask 是允许集 \\(\\{(t,s):d(t)=d(s)\\}\\) 与因果约束的交，加在 softmax 前。</li><li>实现可以是稠密矩阵、<code>cu_seqlens</code> 分段、或 document_id 比较；语义相同，复杂度不同。</li><li>位置重置、KV 可见页、全局注意力层是否遵守 \\(\\mathcal{A}\\)，都要单独规定。</li><li>分隔 token 不删除边；滑窗切断的是距离不是文档。</li><li>训练与推理必须同一张图，否则 packing 等价性在服务端失效。</li><li>出处：Krell et al., arXiv:2107.02027；FlashAttention varlen；Vaswani 因果掩码。</li></ul>',9))])}const f=r(c,[["render",p]]);export{_ as __pageData,f as default};
